package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.agent.AgentEvent;
import io.github.diodeme.ji.agent.AgentCompaction;
import io.github.diodeme.ji.agent.AgentRun;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.agent.RuntimeConfiguration;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.CancellationSource;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ProviderFailure;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.extension.WorkspaceProvider;
import io.github.diodeme.ji.extension.PromptAssembler;
import io.github.diodeme.ji.extension.PromptContributor;
import io.github.diodeme.ji.session.SessionSnapshot;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import io.github.diodeme.ji.session.tree.SessionInputCoordinator;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.concurrent.CancellationException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Flow;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

final class CoreAgentSession implements AgentSession {
    private final RuntimeConfiguration configuration;
    private final EventPublisher events;
    private final ToolBatchScheduler toolScheduler;
    private final AtomicReference<SessionDocument> document;
    private final AtomicReference<RunHandle> active = new AtomicReference<>();
    private final AtomicReference<CompactionHandle> activeCompaction = new AtomicReference<>();
    private final AtomicBoolean closed = new AtomicBoolean();

    CoreAgentSession(RuntimeConfiguration configuration, SessionDocument initial,
                     ToolBatchScheduler toolScheduler) {
        this.configuration = configuration;
        this.toolScheduler = toolScheduler;
        this.document = new AtomicReference<>(initial);
        this.events = new EventPublisher();
    }

    @Override
    public String id() {
        return document.get().metadata().sessionId();
    }

    @Override
    public AgentRun prompt(String text) {
        return prompt(configuration.idGenerator().next("run"), text);
    }

    @Override
    public AgentRun prompt(String runId, String text) {
        if (closed.get()) throw error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id()));
        if (runId == null || runId.isBlank()) {
            throw error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                    Map.of("protocol", "java-api", "reason", "runId_blank"));
        }
        if (text == null || text.isBlank()) {
            throw error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                    Map.of("protocol", "java-api", "reason", "prompt_blank"));
        }
        compactBeforePrompt();
        RunHandle handle = new RunHandle(runId);
        RunHandle current = active.get();
        if (!active.compareAndSet(null, handle)) {
            String activeRunId = current == null ? "unknown" : current.id();
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", activeRunId));
        }
        try {
            startRun(handle, text);
            configuration.executor().execute(() -> execute(handle));
            return handle;
        } catch (RuntimeException failure) {
            recoverUncommittedRun(handle, failure);
            throw failure;
        }
    }

    @Override
    public AgentRun resume() {
        if (closed.get()) throw error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id()));
        SessionDocument current = currentDocument();
        CanonicalSessionState.Run run = current.execution().activeRun()
                .orElseThrow(() -> error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                        Map.of("protocol", "java-api", "reason", "run_not_paused")));
        if (run.status() != CanonicalSessionState.RunStatus.PAUSED
                || run.pauseReason().orElse(null) != CanonicalSessionState.RunPauseReason.HOST_RESTART) {
            throw error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                    Map.of("protocol", "java-api", "reason", "run_not_restart_paused"));
        }
        RunHandle handle = new RunHandle(run.id().value());
        handle.overflowRecoveryAttempted = hasOverflowRecovery(current, run.id().value());
        if (!active.compareAndSet(null, handle)) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", active.get().id()));
        }
        try {
            CanonicalSessionState.Turn pausedTurn = run.turns().getLast();
            boolean resumesTools = pausedTurn.pausedFrom().orElseThrow()
                    == CanonicalSessionState.TurnPhase.WAITING_FOR_TOOLS;
            SessionDocument resumed;
            if (resumesTools) {
                requireToolRecoverySafe(current, pausedTurn);
                List<SessionDocument.ToolResumeStart> starts = pausedTurn.tools().stream()
                        .filter(tool -> tool.status() == CanonicalSessionState.ToolStatus.PAUSED)
                        .map(tool -> new SessionDocument.ToolResumeStart(
                                tool.id().value(), configuration.idGenerator().next("attempt"),
                                configuration.idGenerator().next("record")))
                        .toList();
                resumed = configuration.sessionRepository().update(
                        id(), current.revision(), value -> value.resumeToolBatch(starts, now()));
            } else {
                resumed = configuration.sessionRepository().update(
                        id(), current.revision(), value -> value.resumeRun(
                                configuration.idGenerator().next("attempt"),
                                configuration.idGenerator().next("message"),
                                configuration.idGenerator().next("record"), now()));
            }
            document.set(resumed);
            configuration.executor().execute(() -> {
                if (resumesTools) executeRecoveredToolBatch(handle);
                else execute(handle);
            });
            return handle;
        } catch (RuntimeException failure) {
            pauseResumedOperation(handle, failure);
            throw failure;
        }
    }

    @Override
    public AgentCompaction compact() {
        return compact("");
    }

    @Override
    public AgentCompaction compact(String customInstructions) {
        if (closed.get()) throw error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id()));
        if (customInstructions == null) {
            throw error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                    Map.of("protocol", "java-api", "reason", "compaction_instructions_null"));
        }
        if (active.get() != null) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", active.get().id()));
        }
        SessionDocument current = currentDocument();
        if (current.execution().activeRun().isPresent()) {
            CanonicalSessionState.Run run = current.execution().activeRun().orElseThrow();
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", run.id().value()));
        }
        CompactionPreparation preparation = prepareCompaction(current);
        if (preparation.messages().isEmpty()) {
            throw error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                    Map.of("protocol", "java-api", "reason", "compaction_not_applicable"));
        }
        CompactionHandle handle = new CompactionHandle(
                configuration.idGenerator().next("compaction"), preparation, customInstructions,
                SessionDocument.CompactionReason.MANUAL);
        if (!activeCompaction.compareAndSet(null, handle)) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", activeCompaction.get().id()));
        }
        try {
            Instant startedAt = now();
            SessionDocument started = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.startCompaction(new SessionDocument.CompactionStart(
                             handle.id(), configuration.idGenerator().next("attempt"),
                             configuration.idGenerator().next("message"),
                             preparation.retainedEntryIds(), preparation.tokensBefore(), customInstructions,
                             handle.reason(), Optional.empty(),
                             configuration.idGenerator().next("record"),
                            configuration.idGenerator().next("record"), startedAt)));
            document.set(started);
            configuration.executor().execute(() -> executeCompaction(handle));
            return handle;
        } catch (RuntimeException failure) {
            failStartedCompaction(handle, failure);
            throw failure;
        }
    }

    @Override
    public AgentCompaction resumeCompaction() {
        if (closed.get()) throw error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id()));
        if (active.get() != null) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", active.get().id()));
        }
        SessionDocument current = currentDocument();
        CanonicalSessionState.Compaction operation = current.execution().compactions().stream()
                .filter(candidate -> candidate.status() == CanonicalSessionState.CompactionStatus.PAUSED)
                .findFirst().orElseThrow(() -> error(ErrorCode.PROTOCOL_INVALID_MESSAGE,
                        Map.of("protocol", "java-api", "reason", "compaction_not_paused")));
        RecoveredCompaction recovered = recoverCompaction(current, operation.id().value());
        CompactionHandle handle = new CompactionHandle(
                operation.id().value(), recovered.preparation(), recovered.customInstructions(), recovered.reason(),
                recovered.reason() == SessionDocument.CompactionReason.OVERFLOW
                        ? recovered.parentRunId() : Optional.empty());
        if (!activeCompaction.compareAndSet(null, handle)) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", activeCompaction.get().id()));
        }
        try {
            SessionDocument resumed = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.resumeCompaction(new SessionDocument.CompactionResume(
                            operation.id().value(), operation.revision(),
                            configuration.idGenerator().next("attempt"),
                            configuration.idGenerator().next("message"),
                            configuration.idGenerator().next("record"), now())));
            document.set(resumed);
            configuration.executor().execute(() -> executeCompaction(handle));
            return handle;
        } catch (RuntimeException failure) {
            pauseResumedCompaction(handle, failure);
            throw failure;
        }
    }

    @Override
    public boolean hasActiveRun() {
        return active.get() != null;
    }

    @Override
    public SessionSnapshot snapshot() {
        return document.get().snapshot();
    }

    @Override
    public List<Message> transcript() {
        return snapshot().transcript();
    }

    @Override
    public Flow.Publisher<AgentEvent> events() {
        return events;
    }

    @Override
    public boolean abort() {
        RunHandle handle = active.get();
        while (handle != null && active.get() == handle
                && !handle.cancellation.token().isCancellationRequested()) {
            SessionDocument current = currentDocument();
            CanonicalSessionState.Run run = current.execution().activeRun().orElse(null);
            if (run == null || !run.id().value().equals(handle.id())) return false;
            if (run.status() == CanonicalSessionState.RunStatus.CANCELLING) return handle.cancelEffect();
            try {
                SessionDocument cancelling = configuration.sessionRepository().update(
                        id(), current.revision(), value -> value.requestAbort(handle.id(), run.revision()));
                remember(cancelling);
                return handle.cancelEffect();
            } catch (IllegalStateException failure) {
                SessionDocument latest = configuration.sessionRepository().load(id())
                        .orElseThrow(() -> error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id())));
                if (latest.revision() <= current.revision()) throw failure;
                remember(latest);
            }
        }
        return false;
    }

    @Override
    public void close() {
        if (!closed.compareAndSet(false, true)) return;
        abort();
        CompactionHandle compaction = activeCompaction.get();
        if (compaction != null) compaction.abort();
        events.close();
    }

    private void startRun(RunHandle handle, String prompt) {
        Instant now = now();
        Message user = new Message(configuration.idGenerator().next("message"), Message.Role.USER,
                List.of(new Content.Text(prompt)), now);
        handle.beforeRun = document.get();
        SessionDocument.RunStart start = new SessionDocument.RunStart(
                handle.id(), configuration.idGenerator().next("turn"),
                configuration.idGenerator().next("attempt"),
                configuration.idGenerator().next("message"), user,
                configuration.idGenerator().next("record"),
                configuration.idGenerator().next("record"), now);
        SessionDocument startedDocument = configuration.sessionRepository().update(
                id(), handle.beforeRun.revision(), current -> current.startRun(start));
        document.set(startedDocument);
        events.emit(new AgentEvent.RunStarted(id(), handle.id(), now));
        events.emit(new AgentEvent.MessageAdded(id(), handle.id(), user, now));
    }

    private void execute(RunHandle handle) {
        try {
            while (true) {
                if (handle.cancellation.token().isCancellationRequested()) {
                    finish(handle, AgentEvent.Outcome.ABORTED, List.of(), Usage.ZERO);
                    return;
                }
                ProviderTurn turn = requestProvider(handle);
                requireProviderCompletionCurrent(handle, turn.operation());
                if (turn.failure != null) {
                    if (recoverContextOverflow(handle, turn.failure)) continue;
                    fail(handle, turn.failure);
                    return;
                }
                if (turn.aborted) {
                    finish(handle, AgentEvent.Outcome.ABORTED, turn.messages, turn.usage);
                    return;
                }
                if (turn.toolCalls.isEmpty()) {
                    if (continueWithSteer(handle, turn)) continue;
                    finish(handle, AgentEvent.Outcome.COMPLETED, turn.messages, turn.usage);
                    return;
                }
                if (!executeTools(handle, turn)) return;
            }
        } catch (CancellationException exception) {
            finishSafely(handle, AgentEvent.Outcome.ABORTED, List.of(), Usage.ZERO, exception);
        } catch (JiException exception) {
            if (exception.error().code() == ErrorCode.OPERATION_STALE_COMPLETION) {
                rejectStaleCompletion(handle, exception);
            } else {
                recoverOrPause(handle, exception);
            }
        } catch (RuntimeException exception) {
            recoverOrPause(handle, exception);
        } finally {
            active.compareAndSet(handle, null);
        }
    }

    private ProviderTurn requestProvider(RunHandle handle) {
        SessionDocument canonical = currentDocument();
        ProviderOperation operation = providerOperation(canonical, handle);
        SessionSnapshot current = canonical.snapshot();
        var promptContext = new PromptContributor.PromptContext(current.sessionId(), current.workingDirectory(),
                configuration.promptLocale(), Map.of(), handle.cancellation.token());
        PromptAssembler.Assembly contributed = new PromptAssembler(configuration.promptTokenCounter())
                .assemble(configuration.promptContributors(), promptContext, configuration.promptTokenBudget());
        String toolGuidelines = configuration.tools().stream()
                .map(ToolDefinition::schema)
                .map(tool -> tool.name() + ": " + tool.description().trim().replaceAll("\\s+", " "))
                .reduce("", (left, right) -> left.isEmpty() ? right : left + "\n" + right);
        String systemPrompt = BuiltinPromptTemplates.system(configuration.promptLocale(), Map.of(
                "workingDirectory", current.workingDirectory(),
                "toolGuidelines", toolGuidelines,
                "context", contributed.text(),
                "skills", ""));
        var request = new ModelRequest(current.sessionId(), current.model(), systemPrompt, canonical.providerContext(),
                configuration.tools().stream().map(ToolDefinition::schema).toList(), Map.of(), handle.cancellation.token());
        var collector = new ProviderCollector(handle.id(), operation);
        configuration.provider().stream(request).subscribe(collector);
        return collector.result.join();
    }

    private ProviderOperation providerOperation(SessionDocument current, RunHandle handle) {
        CanonicalSessionState.Run run = activeRun(current, handle);
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.Attempt attempt = turn.attempts().getLast();
        if (run.status() == CanonicalSessionState.RunStatus.CANCELLING
                && handle.cancellation.token().isCancellationRequested()) {
            throw new CancellationException("Provider dispatch cancelled before start");
        }
        if (run.status() != CanonicalSessionState.RunStatus.RUNNING
                || turn.status() != CanonicalSessionState.TurnStatus.MODEL_STREAMING
                || attempt.status() != CanonicalSessionState.AttemptStatus.RUNNING
                || attempt.step() != CanonicalSessionState.AttemptStep.ASSISTANT) {
            throw staleTool(attempt.id().value(), attempt.revision());
        }
        return new ProviderOperation(
                run.id().value(), turn.id().value(), turn.revision(),
                attempt.id().value(), attempt.revision());
    }

    private void requireProviderCompletionCurrent(RunHandle handle, ProviderOperation operation) {
        SessionDocument current = currentDocument();
        boolean valid = active.get() == handle && current.execution().activeRun().stream()
                .filter(run -> run.id().value().equals(operation.runId()))
                .filter(run -> run.status() == CanonicalSessionState.RunStatus.RUNNING
                        || run.status() == CanonicalSessionState.RunStatus.CANCELLING)
                .flatMap(run -> run.turns().stream())
                .filter(turn -> turn.id().value().equals(operation.turnId())
                        && turn.revision() == operation.turnRevision()
                        && turn.status() == CanonicalSessionState.TurnStatus.MODEL_STREAMING)
                .flatMap(turn -> turn.attempts().stream())
                .anyMatch(attempt -> attempt.id().value().equals(operation.attemptId())
                        && attempt.revision() == operation.attemptRevision()
                        && attempt.status() == CanonicalSessionState.AttemptStatus.RUNNING);
        if (!valid) throw staleTool(operation.attemptId(), operation.attemptRevision());
    }

    private CompactionPreparation prepareCompaction(SessionDocument current) {
        List<SessionDocument.Entry> messages = current.branch("main").stream()
                .filter(entry -> entry.kind() == SessionDocument.EntryKind.MESSAGE).toList();
        List<Message> context = current.providerContext();
        if (messages.isEmpty() || context.isEmpty()) return new CompactionPreparation(List.of(), List.of(), 0);
        int firstRetained = messages.size();
        long retainedTokens = 0;
        int budget = configuration.compactionPolicy().keepRecentTokens();
        while (firstRetained > 0) {
            Message candidate = messages.get(firstRetained - 1).message().orElseThrow();
            long tokens = estimatedTokens(candidate);
            if (firstRetained < messages.size() && retainedTokens + tokens > budget) break;
            retainedTokens = Math.addExact(retainedTokens, tokens);
            firstRetained--;
        }
        while (firstRetained > 0
                && messages.get(firstRetained).message().orElseThrow().role() != Message.Role.USER) {
            firstRetained--;
        }
        List<String> retainedIds = messages.subList(firstRetained, messages.size()).stream()
                .map(SessionDocument.Entry::id).toList();
        int summarizedCount = context.size() - retainedIds.size();
        if (summarizedCount <= 0) return new CompactionPreparation(List.of(), retainedIds, contextTokens(context));
        return new CompactionPreparation(
                List.copyOf(context.subList(0, summarizedCount)), retainedIds, contextTokens(context));
    }

    private Optional<String> compactAutomatically(
            Usage usage, String parentRunId, SessionDocument.CompactionReason reason) {
        if (!configuration.compactionPolicy().automatic()
                || reason == SessionDocument.CompactionReason.THRESHOLD
                && !configuration.compactionPolicy().shouldCompact(usage)) return Optional.empty();
        SessionDocument current = currentDocument();
        CompactionPreparation preparation = prepareCompaction(current);
        if (preparation.messages().isEmpty()) return Optional.empty();
        CompactionHandle handle = new CompactionHandle(
                configuration.idGenerator().next("compaction"), preparation, "", reason);
        if (!activeCompaction.compareAndSet(null, handle)) return Optional.empty();
        try {
            Instant startedAt = now();
            SessionDocument started = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.startCompaction(new SessionDocument.CompactionStart(
                            handle.id(), configuration.idGenerator().next("attempt"),
                            configuration.idGenerator().next("message"),
                            preparation.retainedEntryIds(), preparation.tokensBefore(), "", handle.reason(),
                            Optional.of(parentRunId),
                            configuration.idGenerator().next("record"),
                            configuration.idGenerator().next("record"), startedAt)));
            document.set(started);
            executeCompaction(handle);
        } catch (RuntimeException failure) {
            failStartedCompaction(handle, failure);
        }
        try {
            handle.completion().join();
            return Optional.of(handle.id());
        } catch (java.util.concurrent.CompletionException failure) {
            return Optional.empty();
        }
    }

    private boolean recoverContextOverflow(RunHandle handle, ProviderFailure failure) {
        if (!failure.code().equals(ErrorCode.PROVIDER_CONTEXT_OVERFLOW.code())
                || !configuration.compactionPolicy().automatic()) return false;
        SessionDocument beforeCompaction = currentDocument();
        if (handle.overflowRecoveryAttempted || hasOverflowRecovery(beforeCompaction, handle.id())) return false;
        handle.overflowRecoveryAttempted = true;
        Optional<String> compactionId = compactAutomatically(
                Usage.ZERO, handle.id(), SessionDocument.CompactionReason.OVERFLOW);
        if (compactionId.isEmpty()) return false;
        SessionDocument current = currentDocument();
        CanonicalSessionState.Run run = activeRun(current, handle);
        CanonicalSessionState.Turn turn = run.turns().getLast();
        SessionDocument next = configuration.sessionRepository().update(
                id(), current.revision(), value -> value.continueAfterOverflowCompaction(
                        new SessionDocument.OverflowRetry(
                                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                                compactionId.orElseThrow(), configuration.idGenerator().next("attempt"),
                                configuration.idGenerator().next("message"),
                                configuration.idGenerator().next("record"), now())));
        document.set(next);
        return true;
    }

    private void compactBeforePrompt() {
        if (!configuration.compactionPolicy().automatic()) return;
        SessionDocument current = currentDocument();
        if (current.execution().activeRun().isPresent()) return;
        Optional<CanonicalSessionState.Run> parent = current.execution().completedRuns().stream()
                .reduce((left, right) -> right);
        if (parent.isEmpty()) return;
        latestRunUsageAfterCompaction(current, parent.orElseThrow().id().value()).ifPresent(usage ->
                compactAutomatically(usage, parent.orElseThrow().id().value(), automaticReason(usage)));
    }

    private Optional<Usage> latestRunUsageAfterCompaction(SessionDocument current, String runId) {
        List<SessionDocument.Record> records = current.records();
        int usageIndex = -1;
        int compactionIndex = -1;
        for (int index = 0; index < records.size(); index++) {
            SessionDocument.Record record = records.get(index);
            if (record.kind() == SessionDocument.RecordKind.USAGE
                    && record.operationId().filter(runId::equals).isPresent()) usageIndex = index;
            if (record.kind() == SessionDocument.RecordKind.STEP_ATTEMPT
                    && record.data().containsKey("compactionId")) compactionIndex = index;
        }
        if (usageIndex < 0 || usageIndex < compactionIndex) return Optional.empty();
        Map<String, Object> data = records.get(usageIndex).data();
        return Optional.of(new Usage(number(data, "inputTokens"), number(data, "outputTokens"),
                number(data, "cacheReadTokens"), number(data, "cacheWriteTokens"),
                number(data, "costMicros")));
    }

    private SessionDocument.CompactionReason automaticReason(Usage usage) {
        return configuration.compactionPolicy().isContextOverflow(usage)
                ? SessionDocument.CompactionReason.OVERFLOW
                : SessionDocument.CompactionReason.THRESHOLD;
    }

    private RecoveredCompaction recoverCompaction(SessionDocument current, String compactionId) {
        SessionDocument.Record start = current.records().stream()
                .filter(record -> record.data().get("compactionId") instanceof String value
                        && value.equals(compactionId))
                .findFirst().orElseThrow(() -> staleTool(compactionId, current.revision()));
        Object retainedValue = start.data().get("retainedEntryIds");
        Object tokensValue = start.data().get("tokensBefore");
        Object instructionsValue = start.data().get("customInstructions");
        Object reasonValue = start.data().get("reason");
        Object parentRunValue = start.data().get("parentRunId");
        if (!(retainedValue instanceof List<?> retained)
                || retained.stream().anyMatch(value -> !(value instanceof String))
                || !(tokensValue instanceof Number tokens)
                || !(instructionsValue instanceof String instructions)
                || !(reasonValue instanceof String reason)
                || parentRunValue != null && !(parentRunValue instanceof String)) {
            throw new IllegalStateException("durable compaction input is invalid");
        }
        List<String> retainedIds = retained.stream().map(String.class::cast).toList();
        List<Message> context = current.providerContext();
        int summarizedCount = context.size() - retainedIds.size();
        if (summarizedCount <= 0) throw new IllegalStateException("durable compaction input has no summary source");
        SessionDocument.CompactionReason compactionReason;
        try {
            compactionReason = SessionDocument.CompactionReason.valueOf(
                    reason.toUpperCase(java.util.Locale.ROOT));
        } catch (IllegalArgumentException invalid) {
            throw new IllegalStateException("durable compaction reason is invalid", invalid);
        }
        return new RecoveredCompaction(
                new CompactionPreparation(context.subList(0, summarizedCount), retainedIds, tokens.longValue()),
                instructions, compactionReason, Optional.ofNullable((String) parentRunValue));
    }

    private static boolean hasOverflowRecovery(SessionDocument current, String runId) {
        return current.records().stream().anyMatch(record ->
                record.operationId().filter(runId::equals).isPresent()
                        && "overflow".equals(record.data().get("reason"))
                        && runId.equals(record.data().get("parentRunId"))
                        && record.data().get("compactionId") instanceof String);
    }

    private long contextTokens(List<Message> messages) {
        long total = 0;
        for (Message message : messages) total = Math.addExact(total, estimatedTokens(message));
        return total;
    }

    private long estimatedTokens(Message message) {
        return configuration.promptTokenCounter().count(message.role().name() + ": " + message.text());
    }

    private void executeCompaction(CompactionHandle handle) {
        try {
            String conversation = handle.preparation().messages().stream()
                    .map(message -> message.role().name().toLowerCase(java.util.Locale.ROOT) + ": " + message.text())
                    .reduce("", (left, right) -> left.isEmpty() ? right : left + "\n\n" + right);
            String prompt = BuiltinPromptTemplates.compaction(configuration.promptLocale(), Map.of(
                    "conversation", conversation,
                    "customInstructions", handle.customInstructions()));
            SessionDocument current = currentDocument();
            var request = new ModelRequest(handle.id(), current.model(), prompt, List.of(), List.of(),
                    Map.of("cacheRetention", "none", "operation", "compaction"), handle.cancellation.token());
            var collector = new CompactionCollector();
            configuration.provider().stream(request).subscribe(collector);
            CompactionProviderResult result = collector.result.join();
            if (result.failure() != null) {
                finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.FAILED,
                        result.failure().code(), new JiException(toError(result.failure())));
                return;
            }
            if (result.aborted()) {
                finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.CANCELLED,
                        ErrorCode.OPERATION_CANCELLED.code(), error(ErrorCode.OPERATION_CANCELLED,
                                Map.of("operationId", handle.id())));
                return;
            }
            if (result.summary().isBlank()) {
                finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.FAILED,
                        ErrorCode.PROVIDER_INVALID_RESPONSE.code(), error(ErrorCode.PROVIDER_INVALID_RESPONSE,
                                Map.of("provider", current.model().provider(), "reason", "empty_compaction")));
                return;
            }
            completeCompaction(handle, result);
        } catch (java.util.concurrent.CompletionException completion) {
            Throwable failure = completion.getCause() == null ? completion : completion.getCause();
            if (failure instanceof JiException stale
                    && stale.error().code() == ErrorCode.OPERATION_STALE_COMPLETION) {
                activeCompaction.compareAndSet(handle, null);
                handle.completion.completeExceptionally(stale);
            } else {
                finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.FAILED,
                        ErrorCode.INTERNAL_UNEXPECTED.code(), failure);
            }
        } catch (RuntimeException failure) {
            finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.FAILED,
                    ErrorCode.INTERNAL_UNEXPECTED.code(), failure);
        }
    }

    private synchronized void completeCompaction(CompactionHandle handle, CompactionProviderResult result) {
        SessionDocument current = currentDocument();
        CanonicalSessionState.Compaction operation = current.execution().compactions().stream()
                .filter(candidate -> candidate.id().value().equals(handle.id()))
                .findFirst().orElseThrow(() -> staleTool(handle.id(), current.revision()));
        CanonicalSessionState.Attempt attempt = operation.attempts().getLast();
        SessionDocument next;
        try {
            next = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.completeCompaction(
                            new SessionDocument.CompactionCompletion(
                                    operation.id().value(), operation.revision(),
                                    attempt.id().value(), attempt.revision(), attempt.resultEntryId(),
                                    result.summary(), handle.preparation().retainedEntryIds(),
                                    handle.preparation().tokensBefore(), result.usage(),
                                    Map.of("reason", handle.reason().name().toLowerCase(java.util.Locale.ROOT)),
                                    configuration.idGenerator().next("record"),
                                    configuration.idGenerator().next("record"), now())));
        } catch (IllegalStateException stale) {
            throw staleTool(handle.id(), operation.revision(), stale);
        }
        document.set(next);
        activeCompaction.compareAndSet(handle, null);
        resumeOverflowParent(handle, next);
        handle.completion.complete(new AgentCompaction.Result(
                handle.id(), result.summary(), handle.preparation().tokensBefore(), result.usage()));
    }

    private void resumeOverflowParent(CompactionHandle compaction, SessionDocument compacted) {
        if (compaction.parentRunToResume().isEmpty()) return;
        String parentRunId = compaction.parentRunToResume().orElseThrow();
        CanonicalSessionState.Run run = compacted.execution().activeRun()
                .filter(candidate -> candidate.id().value().equals(parentRunId))
                .orElseThrow(() -> staleTool(parentRunId, compacted.revision()));
        CanonicalSessionState.Turn turn = run.turns().getLast();
        if (run.status() != CanonicalSessionState.RunStatus.PAUSED
                || run.pauseReason().orElse(null) != CanonicalSessionState.RunPauseReason.HOST_RESTART
                || turn.status() != CanonicalSessionState.TurnStatus.PAUSED
                || turn.pausedFrom().orElse(null) != CanonicalSessionState.TurnPhase.WAITING_FOR_COMPACTION) {
            throw staleTool(parentRunId, run.revision());
        }
        RunHandle handle = new RunHandle(parentRunId);
        handle.overflowRecoveryAttempted = true;
        if (!active.compareAndSet(null, handle)) {
            throw error(ErrorCode.SESSION_ACTIVE_RUN,
                    Map.of("sessionId", id(), "runId", active.get().id()));
        }
        try {
            SessionDocument resumed = configuration.sessionRepository().update(
                    id(), compacted.revision(), value -> value.resumeRun(
                            configuration.idGenerator().next("attempt"),
                            configuration.idGenerator().next("message"),
                            configuration.idGenerator().next("record"), now()));
            document.set(resumed);
            configuration.executor().execute(() -> execute(handle));
        } catch (RuntimeException failure) {
            pauseResumedOperation(handle, failure);
            throw failure;
        }
    }

    private synchronized void finishCompactionFailure(
            CompactionHandle handle, CanonicalSessionState.CompactionOutcome outcome,
            String errorCode, Throwable failure) {
        try {
            SessionDocument current = currentDocument();
            CanonicalSessionState.Compaction operation = current.execution().compactions().stream()
                    .filter(candidate -> candidate.id().value().equals(handle.id()))
                    .findFirst().orElse(null);
            if (operation != null && operation.status() == CanonicalSessionState.CompactionStatus.RUNNING) {
                CanonicalSessionState.Attempt attempt = operation.attempts().getLast();
                SessionDocument next = configuration.sessionRepository().update(
                        id(), current.revision(), value -> value.failCompaction(new SessionDocument.CompactionFailure(
                                operation.id().value(), operation.revision(), attempt.id().value(), attempt.revision(),
                                outcome, errorCode, configuration.idGenerator().next("record"), now())));
                document.set(next);
            }
        } catch (RuntimeException persistenceFailure) {
            failure.addSuppressed(persistenceFailure);
        }
        activeCompaction.compareAndSet(handle, null);
        handle.completion.completeExceptionally(failure);
    }

    private void failStartedCompaction(CompactionHandle handle, RuntimeException failure) {
        finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.FAILED,
                ErrorCode.INTERNAL_UNEXPECTED.code(), failure);
    }

    private void pauseResumedOperation(RunHandle handle, RuntimeException failure) {
        try {
            SessionDocument current = currentDocument();
            if (current.execution().activeRun().filter(run -> run.id().value().equals(handle.id())
                    && run.status() == CanonicalSessionState.RunStatus.RUNNING).isPresent()) {
                SessionDocument paused = configuration.sessionRepository().update(
                        id(), current.revision(), SessionDocument::pauseAfterRestart);
                document.set(paused);
            }
        } catch (RuntimeException pauseFailure) {
            failure.addSuppressed(pauseFailure);
        }
        active.compareAndSet(handle, null);
        handle.completion.completeExceptionally(failure);
    }

    private void pauseResumedCompaction(CompactionHandle handle, RuntimeException failure) {
        try {
            SessionDocument current = currentDocument();
            boolean running = current.execution().compactions().stream().anyMatch(compaction ->
                    compaction.id().value().equals(handle.id())
                            && compaction.status() == CanonicalSessionState.CompactionStatus.RUNNING);
            if (running) {
                SessionDocument paused = configuration.sessionRepository().update(
                        id(), current.revision(), SessionDocument::pauseAfterRestart);
                document.set(paused);
            }
        } catch (RuntimeException pauseFailure) {
            failure.addSuppressed(pauseFailure);
        }
        activeCompaction.compareAndSet(handle, null);
        handle.completion.completeExceptionally(failure);
    }

    private boolean executeTools(RunHandle handle, ProviderTurn providerTurn) {
        SessionDocument before = document.get();
        CanonicalSessionState.Run run = before.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.Attempt assistantAttempt = turn.attempts().getLast();
        Instant preparedAt = now();
        WorkspaceProvider.WorkspaceIdentity workspace = new WorkspaceProvider.WorkspaceIdentity(
                before.workingDirectory(), 0);
        var work = new ArrayList<ToolWork>();
        for (Content.ToolCall call : providerTurn.toolCalls) {
            ToolDefinition tool = configuration.tools().stream()
                    .filter(candidate -> candidate.schema().name().equals(call.name()))
                    .findFirst().orElse(null);
            if (tool == null) {
                fail(handle, new ProviderFailure("tool.not_found", Map.of("tool", call.name()), Optional.empty()));
                return false;
            }
            String executionId = configuration.idGenerator().next("tool-execution");
            String attemptId = configuration.idGenerator().next("attempt");
            String resultEntryId = configuration.idGenerator().next("message");
            String permissionId = configuration.idGenerator().next("permission");
            ToolExecutionPolicy.Context previewContext = new ToolExecutionPolicy.Context(
                    "embedded", id(), "embedded", "in-process", workspace, call.id(), call.name(),
                    call.arguments(), 0, preparedAt);
            boolean asks = configuration.toolExecutionPolicy().evaluate(previewContext).action()
                    == ToolExecutionPolicy.Action.ASK;
            PermissionDecider.Request permission = new PermissionDecider.Request(
                    permissionId, "embedded", id(), "embedded", workspace,
                    call.id(), call.name(), call.arguments(), 0, preparedAt,
                    preparedAt.plus(Duration.ofMinutes(30)));
            SessionDocument.ToolStart start = new SessionDocument.ToolStart(
                    executionId, attemptId, resultEntryId, call.id(), call.name(),
                    canonicalRetry(tool.retryContract()), Optional.empty(),
                    asks ? Optional.of(new SessionDocument.PermissionStart(
                            permissionId, permission.expiresAt())) : Optional.empty(),
                    configuration.idGenerator().next("record"));
            work.add(new ToolWork(call, tool, start, 0, permission, null, asks));
        }
        SessionDocument.AssistantCompletion completion = new SessionDocument.AssistantCompletion(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                assistantAttempt.id().value(), assistantAttempt.revision(), providerTurn.messages,
                providerTurn.usage, work.stream().map(ToolWork::start).toList(),
                configuration.idGenerator().next("record"), preparedAt);
        SessionDocument waiting = configuration.sessionRepository().update(
                id(), before.revision(), current -> current.completeAssistantWithTools(completion));
        document.set(waiting);
        for (Message message : providerTurn.messages) {
            events.emit(new AgentEvent.MessageAdded(id(), handle.id(), message, preparedAt));
        }
        events.emit(new AgentEvent.UsageChanged(id(), handle.id(), waiting.usage(), preparedAt));
        return executeToolBatch(handle, providerTurn.usage(), work, workspace, preparedAt);
    }

    private boolean executeToolBatch(
            RunHandle handle, Usage boundaryUsage, List<ToolWork> work,
            WorkspaceProvider.WorkspaceIdentity workspace, Instant preparedAt) {
        try {
            var requests = new ArrayList<ToolBatchScheduler.ToolRequest<ToolDefinition.ToolResult>>();
            for (ToolWork item : work) {
                Content.ToolCall call = item.call();
                SessionDocument.ToolStart start = item.start();
                ToolExecutionPolicy.Context context = new ToolExecutionPolicy.Context(
                        "embedded", id(), "embedded", "in-process", workspace,
                        call.id(), call.name(), call.arguments(), 0, preparedAt);
                if (item.asks()) {
                    events.emit(new AgentEvent.PermissionChanged(id(), handle.id(), item.permission(),
                            AgentEvent.PermissionStatus.PENDING, now()));
                }
                events.emit(new AgentEvent.ToolChanged(id(), handle.id(), call.id(), call.name(),
                        AgentEvent.ToolStatus.PENDING, call.arguments(), "", now()));
                requests.add(new ToolBatchScheduler.ToolRequest<>(
                        context, start.executionId(), item.preparedRevision(), item.permission(),
                        item.tool().retryContract(), null,
                        new ToolBatchScheduler.Lifecycle() {
                            @Override public void permissionResolved(PermissionDecider.Decision decision) {
                                commitPermissionDecision(handle, item, decision);
                            }

                            @Override public long started(String operationId, long preparedRevision) {
                                return commitToolStarted(handle, item, preparedRevision);
                            }
                        },
                        revision -> toolCompletionIsCurrent(handle, start.executionId(), revision),
                        () -> executeToolEffect(item.tool(), call, handle), item.admittedPermission()));
            }
            ToolBatchScheduler.BatchResult<ToolDefinition.ToolResult> batch =
                    toolScheduler.execute(requests, handle.cancellation.token()).toCompletableFuture().join();
            handle.cancellation.token().throwIfCancellationRequested();

            SessionDocument current = document.get();
            CanonicalSessionState.Run currentRun = current.execution().activeRun().orElseThrow();
            CanonicalSessionState.Turn currentTurn = currentRun.turns().getLast();
            var results = new ArrayList<SessionDocument.ToolResult>();
            for (int index = 0; index < work.size(); index++) {
                ToolWork item = work.get(index);
                ToolDefinition.ToolResult value = batch.items().get(index).value();
                long completionRevision = batch.items().get(index).operationRevision();
                CanonicalSessionState.ToolExecution canonicalTool = currentTurn.tools().stream()
                        .filter(candidate -> candidate.id().value().equals(item.start().executionId()))
                        .findFirst().orElseThrow();
                CanonicalSessionState.Attempt canonicalAttempt = canonicalTool.attempts().getLast();
                Message message = new Message(item.start().resultEntryId(), Message.Role.TOOL,
                        List.of(new Content.Text(value.text())), Optional.of(item.call().id()), now());
                results.add(new SessionDocument.ToolResult(
                        canonicalTool.id().value(), completionRevision,
                        canonicalAttempt.id().value(), canonicalAttempt.revision(), message,
                        CanonicalSessionState.ToolOutcome.SUCCEEDED,
                        item.asks() ? Optional.of(CanonicalSessionState.PermissionOutcome.ALLOWED) : Optional.empty()));
            }
            SessionDocument.ToolBatchCompletion toolCompletion = new SessionDocument.ToolBatchCompletion(
                    currentRun.id().value(), currentRun.revision(), currentTurn.id().value(),
                    currentTurn.revision(), results, now());
            SessionDocument toolsCompleted = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.completeToolBatch(toolCompletion));
            document.set(toolsCompleted);
            for (int index = 0; index < work.size(); index++) {
                ToolWork item = work.get(index);
                SessionDocument.ToolResult result = results.get(index);
                if (item.asks()) {
                    events.emit(new AgentEvent.PermissionChanged(id(), handle.id(), item.permission(),
                            AgentEvent.PermissionStatus.ALLOWED, now()));
                }
                events.emit(new AgentEvent.ToolChanged(id(), handle.id(), item.call().id(), item.call().name(),
                        AgentEvent.ToolStatus.COMPLETED, item.call().arguments(), result.message().text(), now()));
                events.emit(new AgentEvent.MessageAdded(id(), handle.id(), result.message(), now()));
            }
            compactAutomatically(boundaryUsage, handle.id(), automaticReason(boundaryUsage));
            beginNextTurn(handle);
            return true;
        } catch (Exception exception) {
            if (handle.cancellation.token().isCancellationRequested()) {
                finish(handle, AgentEvent.Outcome.ABORTED, List.of(), Usage.ZERO);
                return false;
            }
            Throwable cause = exception instanceof java.util.concurrent.CompletionException
                    && exception.getCause() != null ? exception.getCause() : exception;
            if (cause instanceof JiException denied
                    && (denied.error().code() == ErrorCode.PERMISSION_DENIED
                    || denied.error().code() == ErrorCode.PERMISSION_EXPIRED)) {
                work.stream().filter(ToolWork::asks).forEach(item ->
                        events.emit(new AgentEvent.PermissionChanged(id(), handle.id(), item.permission(),
                                AgentEvent.PermissionStatus.DENIED, now())));
                finish(handle, AgentEvent.Outcome.DECLINED, List.of(), Usage.ZERO);
                return false;
            }
            if (cause instanceof JiException stale
                    && stale.error().code() == ErrorCode.OPERATION_STALE_COMPLETION) {
                rejectStaleCompletion(handle, stale);
                return false;
            }
            String failureCode = cause instanceof JiException denied
                    && denied.error().code() == ErrorCode.TOOL_POLICY_DENIED
                    ? "tool.policy_denied" : "tool.execution_failed";
            String toolName = work.isEmpty() ? "unknown" : work.getFirst().call().name();
            fail(handle, new ProviderFailure(failureCode, Map.of("tool", toolName), Optional.empty()));
            return false;
        }
    }

    private void executeRecoveredToolBatch(RunHandle handle) {
        try {
            SessionDocument current = currentDocument();
            CanonicalSessionState.Run run = activeRun(current, handle);
            CanonicalSessionState.Turn turn = run.turns().getLast();
            if (turn.status() != CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS) {
                throw staleTool(run.id().value(), run.revision());
            }
            Instant recoveredAt = now();
            WorkspaceProvider.WorkspaceIdentity workspace = new WorkspaceProvider.WorkspaceIdentity(
                    current.workingDirectory(), 0);
            var work = new ArrayList<ToolWork>();
            for (CanonicalSessionState.ToolExecution canonical : turn.tools()) {
                ToolDefinition tool = configuration.tools().stream()
                        .filter(candidate -> candidate.schema().name().equals(canonical.toolName()))
                        .findFirst().orElseThrow(() -> error(ErrorCode.TOOL_NOT_FOUND,
                                Map.of("tool", canonical.toolName())));
                Content.ToolCall call = recoveredToolCall(current, canonical);
                CanonicalSessionState.Attempt attempt = canonical.attempts().getLast();
                Optional<CanonicalSessionState.Permission> canonicalPermission = turn.permissions().stream()
                        .filter(permission -> permission.toolExecutionId().equals(canonical.id())).findFirst();
                canonicalPermission.filter(permission ->
                                permission.status() == CanonicalSessionState.PermissionStatus.RESOLVED
                                        && permission.outcome().orElseThrow()
                                        != CanonicalSessionState.PermissionOutcome.ALLOWED)
                        .ifPresent(permission -> {
                            throw error(ErrorCode.PERMISSION_DENIED,
                                    Map.of("permissionId", permission.id().value(), "tool", call.name()));
                        });
                PermissionDecider.Request permission = canonicalPermission
                        .map(value -> recoveredPermission(value, call, workspace, recoveredAt)).orElse(null);
                PermissionDecider.Decision admittedPermission = canonicalPermission
                        .filter(value -> value.status() == CanonicalSessionState.PermissionStatus.RESOLVED)
                        .map(value -> new PermissionDecider.Decision(
                                value.id().value(), permission.revision(), value.revision(),
                                PermissionDecider.Outcome.ALLOW, recoveredAt))
                        .orElse(null);
                SessionDocument.ToolStart start = new SessionDocument.ToolStart(
                        canonical.id().value(), attempt.id().value(), canonical.resultEntryId(),
                        canonical.toolCallId(), canonical.toolName(), canonical.retryContract(), canonical.resumeToken(),
                        canonicalPermission.map(value -> new SessionDocument.PermissionStart(
                                value.id().value(), value.expiresAt())),
                        configuration.idGenerator().next("record"));
                work.add(new ToolWork(call, tool, start, canonical.revision(),
                        permission, admittedPermission, canonicalPermission.isPresent()));
            }
            if (executeToolBatch(handle, recoveredBoundaryUsage(current, run.id().value()),
                    work, workspace, recoveredAt)) {
                execute(handle);
            }
        } catch (CancellationException exception) {
            finishSafely(handle, AgentEvent.Outcome.ABORTED, List.of(), Usage.ZERO, exception);
        } catch (JiException exception) {
            if (exception.error().code() == ErrorCode.OPERATION_STALE_COMPLETION) {
                rejectStaleCompletion(handle, exception);
            } else {
                pauseResumedOperation(handle, exception);
            }
        } catch (RuntimeException exception) {
            pauseResumedOperation(handle, exception);
        } finally {
            active.compareAndSet(handle, null);
        }
    }

    private static Content.ToolCall recoveredToolCall(
            SessionDocument current, CanonicalSessionState.ToolExecution tool) {
        List<Message> context = current.providerContext();
        for (int messageIndex = context.size() - 1; messageIndex >= 0; messageIndex--) {
            List<Content> content = context.get(messageIndex).content();
            for (int contentIndex = content.size() - 1; contentIndex >= 0; contentIndex--) {
                Content value = content.get(contentIndex);
                if (value instanceof Content.ToolCall call && call.id().equals(tool.toolCallId())
                        && call.name().equals(tool.toolName())) return call;
            }
        }
        throw new IllegalStateException("durable Tool call input is missing");
    }

    private static void requireToolRecoverySafe(
            SessionDocument current, CanonicalSessionState.Turn turn) {
        var started = current.records().stream()
                .filter(record -> record.kind() == SessionDocument.RecordKind.TOOL_STARTED)
                .map(record -> record.data().get("toolExecutionId"))
                .filter(String.class::isInstance).map(String.class::cast)
                .collect(java.util.stream.Collectors.toSet());
        turn.tools().stream()
                .filter(tool -> tool.status() == CanonicalSessionState.ToolStatus.PAUSED)
                .filter(tool -> started.contains(tool.id().value()) && !tool.mayResume())
                .findFirst().ifPresent(tool -> {
                    throw error(ErrorCode.TOOL_EXECUTION_FAILED, Map.of("tool", tool.toolName()));
                });
    }

    private static PermissionDecider.Request recoveredPermission(
            CanonicalSessionState.Permission permission, Content.ToolCall call,
            WorkspaceProvider.WorkspaceIdentity workspace, Instant recoveredAt) {
        long requestRevision = permission.status() == CanonicalSessionState.PermissionStatus.PENDING
                ? permission.revision() : Math.max(0, permission.revision() - 1);
        Instant createdAt = permission.expiresAt().minus(Duration.ofMinutes(30));
        return new PermissionDecider.Request(
                permission.id().value(), "embedded", permission.sessionId().value(), "embedded", workspace,
                call.id(), call.name(), call.arguments(), requestRevision, createdAt, permission.expiresAt());
    }

    private static Usage recoveredBoundaryUsage(SessionDocument current, String runId) {
        List<SessionDocument.Record> records = current.records();
        for (int index = records.size() - 1; index >= 0; index--) {
            SessionDocument.Record record = records.get(index);
            if (record.kind() != SessionDocument.RecordKind.USAGE
                    || !record.operationId().filter(runId::equals).isPresent()) continue;
            Map<String, Object> data = record.data();
            return new Usage(number(data, "inputTokens"), number(data, "outputTokens"),
                    number(data, "cacheReadTokens"), number(data, "cacheWriteTokens"),
                    number(data, "costMicros"));
        }
        return Usage.ZERO;
    }

    private static long number(Map<String, Object> data, String name) {
        Object value = data.get(name);
        if (value instanceof Number number) return number.longValue();
        throw new IllegalStateException("durable usage field is invalid: " + name);
    }

    private void rejectStaleCompletion(RunHandle handle, JiException failure) {
        currentDocument();
        active.compareAndSet(handle, null);
        handle.completion.completeExceptionally(failure);
    }

    private synchronized void commitPermissionDecision(
            RunHandle handle, ToolWork work, PermissionDecider.Decision decision) {
        SessionDocument current = currentDocument();
        CanonicalSessionState.Run run = activeRun(current, handle);
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.ToolExecution tool = currentTool(turn, work.start().executionId());
        CanonicalSessionState.Permission permission = turn.permissions().stream()
                .filter(candidate -> candidate.id().value().equals(decision.permissionId()))
                .findFirst().orElseThrow(() -> staleTool(work.start().executionId(), decision.requestRevision()));
        CanonicalSessionState.PermissionOutcome outcome = decision.outcome() == PermissionDecider.Outcome.ALLOW
                ? CanonicalSessionState.PermissionOutcome.ALLOWED
                : CanonicalSessionState.PermissionOutcome.DENIED;
        SessionDocument.ToolPermissionResolution resolution = new SessionDocument.ToolPermissionResolution(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                tool.id().value(), tool.revision(), permission.id().value(), decision.requestRevision(),
                outcome, configuration.idGenerator().next("record"), decision.decidedAt());
        try {
            SessionDocument next = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.resolveToolPermission(resolution));
            document.set(next);
        } catch (IllegalStateException stale) {
            throw staleTool(work.start().executionId(), decision.requestRevision(), stale);
        }
        events.emit(new AgentEvent.PermissionChanged(
                id(), handle.id(), work.permission(),
                outcome == CanonicalSessionState.PermissionOutcome.ALLOWED
                        ? AgentEvent.PermissionStatus.ALLOWED : AgentEvent.PermissionStatus.DENIED,
                decision.decidedAt()));
    }

    private synchronized long commitToolStarted(RunHandle handle, ToolWork work, long preparedRevision) {
        SessionDocument current = currentDocument();
        CanonicalSessionState.Run run = activeRun(current, handle);
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.ToolExecution tool = currentTool(turn, work.start().executionId());
        CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
        SessionDocument.ToolExecutionStart start = new SessionDocument.ToolExecutionStart(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                tool.id().value(), preparedRevision, attempt.id().value(), attempt.revision(),
                configuration.idGenerator().next("record"), now());
        SessionDocument next;
        try {
            next = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.startTool(start));
            document.set(next);
        } catch (IllegalStateException stale) {
            throw staleTool(work.start().executionId(), preparedRevision, stale);
        }
        CanonicalSessionState.ToolExecution running = next.execution().activeRun().orElseThrow()
                .turns().getLast().tools().stream()
                .filter(candidate -> candidate.id().value().equals(work.start().executionId()))
                .findFirst().orElseThrow();
        events.emit(new AgentEvent.ToolChanged(id(), handle.id(), work.call().id(), work.call().name(),
                AgentEvent.ToolStatus.RUNNING, work.call().arguments(), "", now()));
        return running.revision();
    }

    private static ToolDefinition.ToolResult executeToolEffect(
            ToolDefinition tool, Content.ToolCall call, RunHandle handle) {
        try {
            return tool.executor().execute(call.arguments(), handle.cancellation.token());
        } catch (RuntimeException exception) {
            throw exception;
        } catch (Exception exception) {
            throw new java.util.concurrent.CompletionException(exception);
        }
    }

    private boolean toolCompletionIsCurrent(RunHandle handle, String executionId, long revision) {
        if (active.get() != handle) return false;
        return configuration.sessionRepository().load(id()).stream()
                .peek(document::set)
                .flatMap(current -> current.execution().activeRun().stream())
                .filter(run -> run.status() == CanonicalSessionState.RunStatus.RUNNING)
                .flatMap(run -> run.turns().stream())
                .filter(turn -> turn.status() == CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS)
                .flatMap(turn -> turn.tools().stream())
                .anyMatch(tool -> tool.id().value().equals(executionId) && tool.revision() == revision
                        && (tool.status() == CanonicalSessionState.ToolStatus.PREPARED
                        || tool.status() == CanonicalSessionState.ToolStatus.RUNNING));
    }

    private SessionDocument currentDocument() {
        SessionDocument current = configuration.sessionRepository().load(id())
                .orElseThrow(() -> error(ErrorCode.SESSION_NOT_FOUND, Map.of("sessionId", id())));
        return remember(current);
    }

    private SessionDocument remember(SessionDocument candidate) {
        return document.accumulateAndGet(candidate,
                (known, loaded) -> loaded.revision() >= known.revision() ? loaded : known);
    }

    private static CanonicalSessionState.Run activeRun(SessionDocument current, RunHandle handle) {
        return current.execution().activeRun()
                .filter(run -> run.id().value().equals(handle.id()))
                .orElseThrow(() -> staleTool(handle.id(), current.revision()));
    }

    private static CanonicalSessionState.ToolExecution currentTool(
            CanonicalSessionState.Turn turn, String executionId) {
        return turn.tools().stream()
                .filter(tool -> tool.id().value().equals(executionId))
                .findFirst().orElseThrow(() -> staleTool(executionId, turn.revision()));
    }

    private static JiException staleTool(String operationId, long completionRevision) {
        return staleTool(operationId, completionRevision, null);
    }

    private static JiException staleTool(String operationId, long completionRevision, Throwable cause) {
        JiError error = new JiError(ErrorCode.OPERATION_STALE_COMPLETION,
                Map.of("operationId", operationId,
                        "completionRevision", Long.toString(completionRevision)),
                Optional.empty(), Optional.empty(), OptionalLong.empty());
        return cause == null ? new JiException(error) : new JiException(error, cause);
    }

    private void beginNextTurn(RunHandle handle) {
        SessionDocument current = document.get();
        CanonicalSessionState.Run run = current.execution().activeRun().orElseThrow();
        Instant startedAt = now();
        String turnId = configuration.idGenerator().next("turn");
        String attemptId = configuration.idGenerator().next("attempt");
        String resultEntryId = configuration.idGenerator().next("message");
        String attemptRecordId = configuration.idGenerator().next("record");
        SessionDocument next;
        if (configuration.sessionRepository() instanceof SessionInputCoordinator coordinator) {
            next = coordinator.beginNextTurn(id(), current.revision(), (value, input) ->
                    value.beginNextTurn(new SessionDocument.TurnStart(
                            run.id().value(), run.revision(), turnId, attemptId, resultEntryId,
                            input.map(item -> queuedMessage(item, startedAt)), attemptRecordId, startedAt)));
        } else {
            SessionDocument.TurnStart start = new SessionDocument.TurnStart(
                    run.id().value(), run.revision(), turnId, attemptId, resultEntryId,
                    Optional.empty(), attemptRecordId, startedAt);
            next = configuration.sessionRepository().update(
                    id(), current.revision(), value -> value.beginNextTurn(start));
        }
        document.set(next);
    }

    private boolean continueWithSteer(RunHandle handle, ProviderTurn providerTurn) {
        if (!(configuration.sessionRepository() instanceof SessionInputCoordinator coordinator)) return false;
        SessionDocument current = document.get();
        CanonicalSessionState.Run run = current.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.Attempt attempt = turn.attempts().getLast();
        Instant completedAt = now();
        String nextTurnId = configuration.idGenerator().next("turn");
        String nextAttemptId = configuration.idGenerator().next("attempt");
        String nextResultEntryId = configuration.idGenerator().next("message");
        String usageRecordId = configuration.idGenerator().next("record");
        String attemptRecordId = configuration.idGenerator().next("record");
        Optional<SessionDocument> continued = coordinator.continueWithSteer(
                id(), current.revision(), (value, input) -> value.continueAssistantWithSteer(
                        new SessionDocument.AssistantSteerContinuation(
                                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                                attempt.id().value(), attempt.revision(), providerTurn.messages,
                                providerTurn.usage, queuedMessage(input, completedAt), nextTurnId,
                                nextAttemptId, nextResultEntryId, usageRecordId, attemptRecordId,
                                completedAt)));
        if (continued.isEmpty()) return false;
        SessionDocument next = continued.orElseThrow();
        document.set(next);
        for (Message message : providerTurn.messages) {
            events.emit(new AgentEvent.MessageAdded(id(), handle.id(), message, completedAt));
        }
        Message steer = next.snapshot().transcript().getLast();
        events.emit(new AgentEvent.MessageAdded(id(), handle.id(), steer, completedAt));
        events.emit(new AgentEvent.UsageChanged(id(), handle.id(), next.usage(), completedAt));
        return true;
    }

    private static Message queuedMessage(SessionInputCoordinator.QueuedInput input, Instant createdAt) {
        List<Content> content = input.content().stream().map(Content.Text::new)
                .map(Content.class::cast).toList();
        if (content.isEmpty()) {
            content = List.of(new Content.Text(String.join("\n", input.attachments())));
        }
        return new Message(input.itemId(), Message.Role.USER, content, createdAt);
    }

    private static CanonicalSessionState.ToolRetryContract canonicalRetry(
            io.github.diodeme.ji.extension.ToolRetryContract value) {
        return switch (io.github.diodeme.ji.extension.ToolRetryContract.failClosed(value)) {
            case READ_ONLY -> CanonicalSessionState.ToolRetryContract.READ_ONLY;
            case IDEMPOTENT -> CanonicalSessionState.ToolRetryContract.IDEMPOTENT;
            case RESUMABLE -> CanonicalSessionState.ToolRetryContract.RESUMABLE;
            case NON_RETRYABLE -> CanonicalSessionState.ToolRetryContract.NON_RETRYABLE;
        };
    }

    private void finish(RunHandle handle, AgentEvent.Outcome outcome, List<Message> messages, Usage usage) {
        SessionDocument next = commitRun(handle, switch (outcome) {
            case COMPLETED -> CanonicalSessionState.RunOutcome.COMPLETED;
            case ABORTED -> CanonicalSessionState.RunOutcome.ABORTED;
            case DECLINED -> CanonicalSessionState.RunOutcome.DECLINED;
        }, messages, usage);
        for (Message message : messages) events.emit(new AgentEvent.MessageAdded(id(), handle.id(), message, now()));
        events.emit(new AgentEvent.UsageChanged(id(), handle.id(), next.usage(), now()));
        if (outcome == AgentEvent.Outcome.COMPLETED) {
            compactAutomatically(usage, handle.id(), automaticReason(usage));
        }
        events.emit(new AgentEvent.RunFinished(id(), handle.id(), outcome, now()));
        active.compareAndSet(handle, null);
        handle.completion.complete(new AgentRun.Result(handle.id(), outcome));
    }

    private void fail(RunHandle handle, ProviderFailure failure) {
        JiError error = toError(failure);
        try {
            if (document.get().execution().activeRun()
                    .filter(run -> run.id().value().equals(handle.id())).isPresent()) {
                commitRun(handle, CanonicalSessionState.RunOutcome.FAILED, List.of(), Usage.ZERO);
            }
        } catch (RuntimeException commitFailure) {
            recoverUncommittedRun(handle, commitFailure);
            return;
        }
        events.emit(new AgentEvent.RunFailed(id(), handle.id(), error, now()));
        active.compareAndSet(handle, null);
        handle.completion.completeExceptionally(new JiException(error));
    }

    private void finishSafely(RunHandle handle, AgentEvent.Outcome outcome, List<Message> messages, Usage usage,
                              RuntimeException originalFailure) {
        try {
            finish(handle, outcome, messages, usage);
        } catch (RuntimeException commitFailure) {
            commitFailure.addSuppressed(originalFailure);
            recoverUncommittedRun(handle, commitFailure);
        }
    }

    private void recoverUncommittedRun(RunHandle handle, RuntimeException failure) {
        SessionDocument baseline = handle.beforeRun;
        if (baseline != null) {
            SessionDocument current = document.get();
            boolean ownsRun = current.execution().activeRun()
                    .filter(run -> run.id().value().equals(handle.id())).isPresent();
            if (ownsRun) {
                try {
                    SessionDocument restored = configuration.sessionRepository().update(
                            id(), current.revision(), value -> value.rollbackRun(handle.id(), baseline));
                    document.set(restored);
                } catch (RuntimeException rollbackFailure) {
                    failure.addSuppressed(rollbackFailure);
                }
            }
        }
        active.compareAndSet(handle, null);
        handle.completion.completeExceptionally(failure);
    }

    private void recoverOrPause(RunHandle handle, RuntimeException failure) {
        if (handle.beforeRun == null) pauseResumedOperation(handle, failure);
        else recoverUncommittedRun(handle, failure);
    }

    private SessionDocument commitRun(
            RunHandle handle, CanonicalSessionState.RunOutcome outcome, List<Message> messages, Usage usage) {
        SessionDocument current = document.get();
        CanonicalSessionState.Run run = current.execution().activeRun()
                .filter(candidate -> candidate.id().value().equals(handle.id()))
                .orElseThrow(() -> new IllegalStateException("Run no longer owns the Session"));
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.Attempt attempt = turn.attempts().getLast();
        SessionDocument.RunCompletion completion = new SessionDocument.RunCompletion(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                attempt.id().value(), attempt.revision(), messages, usage,
                outcome,
                configuration.idGenerator().next("record"),
                configuration.idGenerator().next("record"), now());
        SessionDocument next = configuration.sessionRepository().update(
                id(), current.revision(), value -> value.finishRun(completion));
        document.set(next);
        return next;
    }

    private JiError toError(ProviderFailure failure) {
        ErrorCode code = switch (failure.code()) {
            case "provider.authentication_failed" -> ErrorCode.PROVIDER_AUTHENTICATION_FAILED;
            case "provider.permission_denied" -> ErrorCode.PROVIDER_PERMISSION_DENIED;
            case "provider.rate_limited" -> ErrorCode.PROVIDER_RATE_LIMITED;
            case "provider.timeout" -> ErrorCode.PROVIDER_TIMEOUT;
            case "provider.unavailable" -> ErrorCode.PROVIDER_UNAVAILABLE;
            case "provider.request_rejected" -> ErrorCode.PROVIDER_REQUEST_REJECTED;
            case "provider.redirect_rejected" -> ErrorCode.PROVIDER_REDIRECT_REJECTED;
            case "provider.invalid_response" -> ErrorCode.PROVIDER_INVALID_RESPONSE;
            case "provider.context_overflow" -> ErrorCode.PROVIDER_CONTEXT_OVERFLOW;
            case "tool.not_found" -> ErrorCode.TOOL_NOT_FOUND;
            case "tool.execution_failed" -> ErrorCode.TOOL_EXECUTION_FAILED;
            case "tool.policy_denied" -> ErrorCode.TOOL_POLICY_DENIED;
            case "operation.cancelled" -> ErrorCode.OPERATION_CANCELLED;
            default -> ErrorCode.INTERNAL_UNEXPECTED;
        };
        return new JiError(code, failure.parameters(), Optional.empty(), failure.retryAfter(), OptionalLong.empty());
    }

    private Instant now() {
        return configuration.clock().instant();
    }

    private final class ProviderCollector implements Flow.Subscriber<ModelStreamEvent> {
        private final CompletableFuture<ProviderTurn> result = new CompletableFuture<>();
        private final String runId;
        private final ProviderOperation operation;
        private final List<Message> messages = new ArrayList<>();
        private final StringBuilder text = new StringBuilder();
        private Flow.Subscription subscription;
        private String responseId;
        private final List<Content.ToolCall> toolCalls = new ArrayList<>();
        private long streamSeq;

        ProviderCollector(String runId, ProviderOperation operation) {
            this.runId = runId;
            this.operation = operation;
        }

        @Override public void onSubscribe(Flow.Subscription value) { subscription = value; value.request(1); }
        @Override public void onNext(ModelStreamEvent event) {
            if (event instanceof ModelStreamEvent.Started started) responseId = started.responseId();
            else if (event instanceof ModelStreamEvent.TextDelta delta) {
                text.append(delta.text());
                events.emit(new AgentEvent.TextStreamed(id(), runId, responseId == null ? runId : responseId,
                        text.toString(), ++streamSeq, now()));
            } else if (event instanceof ModelStreamEvent.ToolCallReady ready) toolCalls.add(ready.toolCall());
            else if (event instanceof ModelStreamEvent.Completed completed) complete(completed.usage(), completed.stopReason() == ModelStreamEvent.StopReason.ABORTED);
            else if (event instanceof ModelStreamEvent.Failed failed) result.complete(new ProviderTurn(
                    List.of(), Usage.ZERO, List.of(), false, failed.failure(), operation));
            subscription.request(1);
        }
        @Override public void onError(Throwable throwable) {
            result.complete(new ProviderTurn(List.of(), Usage.ZERO, List.of(), false,
                    new ProviderFailure("internal.unexpected", Map.of(), Optional.empty()), operation));
        }
        @Override public void onComplete() {
            if (!result.isDone()) onError(new IllegalStateException("provider stream ended without terminal event"));
        }
        private void complete(Usage usage, boolean aborted) {
            if (!text.isEmpty() || !toolCalls.isEmpty()) {
                var content = new ArrayList<Content>();
                if (!text.isEmpty()) content.add(new Content.Text(text.toString()));
                content.addAll(toolCalls);
                messages.add(new Message(configuration.idGenerator().next("message"), Message.Role.ASSISTANT, content, now()));
            }
            result.complete(new ProviderTurn(
                    List.copyOf(messages), usage, List.copyOf(toolCalls), aborted, null, operation));
        }
    }

    private record ProviderTurn(List<Message> messages, Usage usage, List<Content.ToolCall> toolCalls,
                                 boolean aborted, ProviderFailure failure, ProviderOperation operation) {}

    private record ProviderOperation(
            String runId, String turnId, long turnRevision, String attemptId, long attemptRevision) {}

    private record CompactionPreparation(
            List<Message> messages, List<String> retainedEntryIds, long tokensBefore) {
        private CompactionPreparation {
            messages = List.copyOf(messages);
            retainedEntryIds = List.copyOf(retainedEntryIds);
            if (tokensBefore < 0) throw new IllegalArgumentException("tokensBefore must be non-negative");
        }
    }

    private record RecoveredCompaction(
            CompactionPreparation preparation, String customInstructions,
            SessionDocument.CompactionReason reason, Optional<String> parentRunId) {}

    private record CompactionProviderResult(
            String summary, Usage usage, boolean aborted, ProviderFailure failure) {}

    private final class CompactionCollector implements Flow.Subscriber<ModelStreamEvent> {
        private final CompletableFuture<CompactionProviderResult> result = new CompletableFuture<>();
        private final StringBuilder text = new StringBuilder();
        private Flow.Subscription subscription;
        private boolean invalidToolCall;

        @Override public void onSubscribe(Flow.Subscription value) {
            subscription = value;
            value.request(1);
        }

        @Override public void onNext(ModelStreamEvent event) {
            if (event instanceof ModelStreamEvent.TextDelta delta) text.append(delta.text());
            else if (event instanceof ModelStreamEvent.ToolCallReady) invalidToolCall = true;
            else if (event instanceof ModelStreamEvent.Completed completed) {
                if (invalidToolCall) {
                    result.complete(new CompactionProviderResult("", Usage.ZERO, false,
                            new ProviderFailure("provider.invalid_response",
                                    Map.of("reason", "compaction_tool_call"), Optional.empty())));
                } else {
                    result.complete(new CompactionProviderResult(
                            text.toString(), completed.usage(),
                            completed.stopReason() == ModelStreamEvent.StopReason.ABORTED, null));
                }
            } else if (event instanceof ModelStreamEvent.Failed failed) {
                result.complete(new CompactionProviderResult("", Usage.ZERO, false, failed.failure()));
            }
            subscription.request(1);
        }

        @Override public void onError(Throwable throwable) {
            result.complete(new CompactionProviderResult("", Usage.ZERO, false,
                    new ProviderFailure("internal.unexpected", Map.of(), Optional.empty())));
        }

        @Override public void onComplete() {
            if (!result.isDone()) onError(new IllegalStateException("provider stream ended without terminal event"));
        }
    }

    private record ToolWork(
            Content.ToolCall call,
            ToolDefinition tool,
            SessionDocument.ToolStart start,
            long preparedRevision,
            PermissionDecider.Request permission,
            PermissionDecider.Decision admittedPermission,
            boolean asks) {}

    private final class RunHandle implements AgentRun {
        private final String id;
        private final CancellationSource cancellation = new CancellationSource();
        private final CompletableFuture<Result> completion = new CompletableFuture<>();
        private SessionDocument beforeRun;
        private boolean overflowRecoveryAttempted;
        RunHandle(String id) { this.id = id; }
        @Override public String id() { return id; }
        @Override public CompletableFuture<Result> completion() { return completion; }
        @Override public boolean abort() { return CoreAgentSession.this.abort(); }
        private boolean cancelEffect() { return cancellation.cancel(); }
    }

    private final class CompactionHandle implements AgentCompaction {
        private final String id;
        private final CompactionPreparation preparation;
        private final String customInstructions;
        private final SessionDocument.CompactionReason reason;
        private final Optional<String> parentRunToResume;
        private final CancellationSource cancellation = new CancellationSource();
        private final CompletableFuture<Result> completion = new CompletableFuture<>();

        private CompactionHandle(
                String id, CompactionPreparation preparation, String customInstructions,
                SessionDocument.CompactionReason reason) {
            this(id, preparation, customInstructions, reason, Optional.empty());
        }

        private CompactionHandle(
                String id, CompactionPreparation preparation, String customInstructions,
                SessionDocument.CompactionReason reason, Optional<String> parentRunToResume) {
            this.id = id;
            this.preparation = preparation;
            this.customInstructions = customInstructions;
            this.reason = reason;
            this.parentRunToResume = parentRunToResume;
        }

        @Override public String id() { return id; }
        @Override public CompletableFuture<Result> completion() { return completion; }
        @Override public boolean abort() { return abortCompaction(this); }
        private CompactionPreparation preparation() { return preparation; }
        private String customInstructions() { return customInstructions; }
        private SessionDocument.CompactionReason reason() { return reason; }
        private Optional<String> parentRunToResume() { return parentRunToResume; }
    }

    private synchronized boolean abortCompaction(CompactionHandle handle) {
        if (activeCompaction.get() != handle || !handle.cancellation.cancel()) return false;
        finishCompactionFailure(handle, CanonicalSessionState.CompactionOutcome.CANCELLED,
                ErrorCode.OPERATION_CANCELLED.code(), error(ErrorCode.OPERATION_CANCELLED,
                        Map.of("operationId", handle.id())));
        return true;
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters) {
        return new JiException(new JiError(code, parameters, Optional.empty(), Optional.empty(), OptionalLong.empty()));
    }
}
